1	/**
2	 * Drive the reusable Angular CLI era adapter over the materialised
3	 * `angular-factoriolab` tree and record what it changed.
4	 *
5	 * The driver is fixture-scoped: it knows where this fixture's tree lives and
6	 * which pinned revision it must be. Every decision about *what* to change lives
7	 * in `@versionless/angular`, which knows nothing about this application.
8	 *
9	 * The record this writes is a source-level migration record. It states which
10	 * files the adapter changed and to which bytes; it does not state that the
11	 * result installs, builds, or behaves like the era baseline, and the record
12	 * carries those as explicit non-claims rather than leaving them to be assumed.
13	 */
14	
15	import { createHash } from 'node:crypto';
16	import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
17	import * as path from 'pathe';
18	import {
19		ANGULAR_16_BROWSER_CELL,
20		migrateAngularCliEraWorkspace,
21		type AngularMigration,
22		type WorkspaceFile,
23	} from '../../../frameworks/angular/src/index.ts';
24	
25	export const FACTORIOLAB_COMMIT = '5f54abbdcac518d8ebf7e136c4348384d9b1a2bb';
26	export const FACTORIOLAB_ARCHIVE_URL =
27		'https://codeload.github.com/factoriolab/factoriolab/tar.gz/5f54abbdcac518d8ebf7e136c4348384d9b1a2bb';
28	export const FACTORIOLAB_ARCHIVE_SHA256 =
29		'11f2ce939f4be04b11e77b7f12e13d7449bf944b9bfefbeca237c46dea12f7ed';
30	export const FACTORIOLAB_ARCHIVE_BYTES = 267218;
31	
32	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
33	const evidenceDirectory = path.join(repositoryRoot, 'evidence/runs/angular-factoriolab');
34	
35	export function sha256(value: string): string {
36		return createHash('sha256').update(value).digest('hex');
37	}
38	
39	export function canonical(value: unknown): string {
40		return `${JSON.stringify(value, null, 2)}\n`;
41	}
42	
43	async function typescriptModulesBelow(directory: string, root: string): Promise<WorkspaceFile[]> {
44		const files: WorkspaceFile[] = [];
45		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
46			left.name < right.name ? -1 : 1,
47		)) {
48			const item = path.join(directory, entry.name);
49			if (entry.isDirectory()) files.push(...(await typescriptModulesBelow(item, root)));
50			else if (entry.isFile() && path.extname(entry.name) === '.ts')
51				files.push({
52					path: path.relative(root, item).split(path.sep).join('/'),
53					source: await readFile(item, 'utf8'),
54				});
55		}
56		return files;
57	}
58	
59	/** Read the four inputs the adapter migrates out of a materialised tree. */
60	export async function readWorkspace(tree: string): Promise<{
61		packageManifest: WorkspaceFile;
62		workspaceConfig: WorkspaceFile;
