67			path: relative,
68			source: await readFile(path.join(tree, relative), 'utf8'),
69		});
70		return {
71			packageManifest: await read('package.json'),
72			workspaceConfig: await read('angular.json'),
73			tsConfig: await read('tsconfig.json'),
74			sourceModules: await typescriptModulesBelow(path.join(tree, 'src'), tree),
75		};
76	}
77	
78	export type MigrationRecord = Readonly<{
79		schemaVersion: 'versionless.angular-factoriolab-source-migration.v1';
80		unit: string;
81		consentId: string;
82		result: 'source-migration-recorded';
83		source: Readonly<{ commit: string; archiveUrl: string; archiveSha256: string; bytes: number }>;
84		cell: Readonly<{
85			id: string;
86			angularLine: string;
87			builder: string;
88			nodeLine: string;
89			typescriptRange: string;
90			rationale: readonly string[];
91		}>;
92		migration: Readonly<{
93			applicationFilesScanned: number;
94			applicationFilesChanged: number;
95			workspaceFilesChanged: number;
96			files: readonly Readonly<{
97				path: string;
98				kind: 'application' | 'workspace';
99				sha256Before: string;
100				sha256After: string;
101				changes: readonly string[];
102			}>[];
103		}>;
104		unhandled: readonly string[];
105		notEstablished: readonly string[];
106		nonclaims: readonly string[];
107		digest: string;
108	}>;
109	
110	const NOT_ESTABLISHED: readonly string[] = Object.freeze([
111		'No dependency install was performed for the target cell, so no package range in this record was resolved against a registry.',
112		'No production build of the migrated tree was attempted; the migrated tree is not known to compile.',
113		'No era baseline build was rebuilt in this unit; the baseline cache recorded by the ingest unit is absent from this workspace.',
114		'No build determinism, dist inventory, entry-shape parity or browser behaviour was observed.',
115	]);
116	
117	const NONCLAIMS: readonly string[] = Object.freeze([
118		'This record states which bytes a set of reusable transforms changed in one pinned tree. It establishes no migration feasibility, no production readiness, no certification and no support claim for Angular applications generally.',
119	]);
120	
121	export function buildMigrationRecord(
122		migration: AngularMigration,
123		unit: string,
124		consentId: string,
125	): MigrationRecord {
126		const body = {
127			schemaVersion: 'versionless.angular-factoriolab-source-migration.v1',
128			unit,
129			consentId,
130			result: 'source-migration-recorded',
131			source: {
132				commit: FACTORIOLAB_COMMIT,
133				archiveUrl: FACTORIOLAB_ARCHIVE_URL,
134				archiveSha256: FACTORIOLAB_ARCHIVE_SHA256,
135				bytes: FACTORIOLAB_ARCHIVE_BYTES,
136			},
137			cell: {
138				id: ANGULAR_16_BROWSER_CELL.id,
139				angularLine: ANGULAR_16_BROWSER_CELL.angularLine,
140				builder: ANGULAR_16_BROWSER_CELL.builder,
141				nodeLine: ANGULAR_16_BROWSER_CELL.nodeLine,
142				typescriptRange: ANGULAR_16_BROWSER_CELL.typescriptRange,
143				rationale: ANGULAR_16_BROWSER_CELL.rationale,
144			},
145			migration: {
146				applicationFilesScanned: migration.applicationFilesScanned,
147				applicationFilesChanged: migration.applicationFilesChanged,
148				workspaceFilesChanged: migration.workspaceFilesChanged,
149				files: migration.files
150					.filter((entry) => entry.changed)
151					.map((entry) => ({
152						path: entry.path,
153						kind: entry.kind,
154						sha256Before: entry.sha256Before,
155						sha256After: entry.sha256After,
156						changes: entry.changes,
157					})),
158			},
159			unhandled: migration.unhandled,
160			notEstablished: NOT_ESTABLISHED,
161			nonclaims: NONCLAIMS,
162		} as const;
163		return Object.freeze({ ...body, digest: sha256(canonical(body)) });
164	}
165	
166	/** Recompute the record's digest; a record that does not seal is rejected. */
167	export function verifyMigrationRecord(record: MigrationRecord): MigrationRecord {
168		const { digest, ...body } = record;
169		const recomputed = sha256(canonical(body));
170		if (recomputed !== digest)
171			throw new Error(
172				`Angular factoriolab migration record digest differs: recorded ${digest}, recomputed ${recomputed}`,
173			);
174		return record;
175	}
176	
177	export async function main(): Promise<void> {
178		const index = process.argv.indexOf('--tree');
179		const tree = index === -1 ? undefined : process.argv[index + 1];
180		if (tree === undefined)
181			throw new Error('Angular factoriolab migration requires --tree <materialised-tree>');
182		const workspace = await readWorkspace(tree);
183		const migration = migrateAngularCliEraWorkspace(workspace, ANGULAR_16_BROWSER_CELL);
184		const record = verifyMigrationRecord(
185			buildMigrationRecord(
186				migration,
187				'lrapr-t005/m1-factoriolab-migration',
188				'VL-LEGACY-CORPUS-2026-08-10',
189			),
190		);
191		const migratedTree = path.join(tree, '..', 'migrated');
192		for (const entry of migration.files) {
193			if (!entry.changed) continue;
194			const destination = path.join(migratedTree, entry.path);
195			await mkdir(path.dirname(destination), { recursive: true });
196			await writeFile(destination, entry.source);
197		}
198		await mkdir(evidenceDirectory, { recursive: true });
199		await writeFile(path.join(evidenceDirectory, 'm1-source-migration.json'), canonical(record));
200		process.stdout.write(canonical(record));
201	}
202	
203	if (process.argv[1]?.endsWith('angular-factoriolab-migration-run.ts'))
204		main().catch((error: unknown) => {
205			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
206			process.exitCode = 1;
207		});
