						`${field}.${name} is coupled to the Angular test cell and was left at its era range`,
					);
				continue;
			}
			updated[name] = range;
			if (range !== from)
				changes.push({ field, name, from, to: range, reason: `aligned to ${cell.id}` });
		}
		next[field] = updated;
	}
	return Object.freeze({
		manifest: Object.freeze(next),
		changes: Object.freeze(changes),
		unhandled: Object.freeze(unhandled.sort(compareStrings)),
	});
}

